Use `limit_req_zone` para limitar requisições por IP:

```nginx
# Definir zona de limitação no contexto http
http {
    limit_req_zone $binary_remote_addr zone=one:10m rate=10r/s;
    limit_req_zone $binary_remote_addr zone=api:10m rate=100r/m;

    # Limitar conexões simultâneas
    limit_conn_zone $binary_remote_addr zone=addr:10m;

    server {
        listen 80;

        location / {
            limit_req zone=one burst=20 nodelay;
            limit_conn addr 10;
            proxy_pass http://backend;
        }

        location /api/ {
            limit_req zone=api burst=50 nodelay;
            proxy_pass http://api_backend;
        }

        # Whitelist para IPs específicos
        location /admin {
            allow 10.0.0.0/8;
            deny all;
            proxy_pass http://backend;
        }
    }
}
```

- `rate=10r/s`: 10 requisições por segundo
- `burst=20`: permite 20 requisições em burst
- `nodelay`: processa bursts imediatamente sem delay

Otimize entrega de assets estáticos:

```nginx
server {
    listen 80;
    server_name exemplo.com;
    root /var/www/html;
    index index.html;

    # Gzip compression
    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_types text/plain text/css application/json application/javascript text/xml;

    # Cache para assets estáticos
    location ~* \.(jpg|jpeg|png|gif|ico|css|js|svg|woff|woff2|ttf)$ {
        expires 1y;
        add_header Cache-Control "public, immutable";
        add_header Vary Accept-Encoding;
        access_log off;
    }

    # HTML nunca cache (para SPAs com client-side routing)
    location ~* \.html$ {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
    }

    # API - sem cache
    location /api/ {
        proxy_pass http://backend;
        add_header Cache-Control "no-store";
    }

    # Client-side routing para SPAs
    location / {
        try_files $uri $uri/ /index.html;
    }
}
```

