Use Pulumi com TypeScript para infraestrutura:

```typescript
// index.ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as awsx from "@pulumi/awsx";

// Configuração
const config = new pulumi.Config();
const environment = config.require("environment");
const projectName = pulumi.getProject();

// VPC
const vpc = new awsx.ec2.Vpc(`${projectName}-vpc`, {
    cidrBlock: "10.0.0.0/16",
    numberOfAvailabilityZones: 2,
    subnets: [
        {
            type: "public",
            cidrMask: 20,
        },
        {
            type: "private",
            cidrMask: 20,
            tags: {
                "kubernetes.io/role/internal-elb": "1",
            },
        },
    ],
    tags: {
        Environment: environment,
    },
});

// ECR Repository
const repo = new aws.ecr.Repository(`${projectName}-repo`, {
    forceDelete: true,
    imageScanningConfiguration: {
        scanOnPush: true,
    },
    tags: {
        Environment: environment,
    },
});

// EKS Cluster
const cluster = new awsx.classic.eks.Cluster(`${projectName}-cluster`, {
    vpcId: vpc.vpcId,
    subnetIds: vpc.privateSubnetIds,
    instanceType: "t3.medium",
    desiredCapacity: 2,
    minSize: 1,
    maxSize: 10,
    tags: {
        Environment: environment,
    },
});

// RDS PostgreSQL
const dbSubnetGroup = new aws.rds.SubnetGroup(`${projectName}-db-subnets`, {
    subnetIds: vpc.privateSubnetIds,
    tags: {
        Environment: environment,
    },
});

const dbSecurityGroup = new aws.ec2.SecurityGroup(`${projectName}-db-sg`, {
    vpcId: vpc.vpcId,
    ingress: [
        {
            protocol: "tcp",
            fromPort: 5432,
            toPort: 5432,
            securityGroups: [cluster.clusterSecurityGroupId],
        },
    ],
    tags: {
        Environment: environment,
    },
});

const db = new aws.rds.Instance(`${projectName}-db`, {
    engine: "postgres",
    engineVersion: "15",
    instanceClass: environment === "production" ? "db.t3.medium" : "db.t3.micro",
    allocatedStorage: 20,
    storageType: "gp2",
    dbName: projectName,
    username: "admin",
    password: config.requireSecret("dbPassword"),
    vpcSecurityGroupIds: [dbSecurityGroup.id],
    dbSubnetGroupName: dbSubnetGroup.name,
    skipFinalSnapshot: environment !== "production",
    tags: {
        Environment: environment,
    },
});

// Exports
export const clusterName = cluster.eksCluster.name;
export const clusterEndpoint = cluster.eksCluster.endpoint;
export const kubeconfig = cluster.kubeconfig;
export const dbEndpoint = db.endpoint;
export const dbPort = db.port;
export const repositoryUrl = repo.repositoryUrl;
```

Configure CloudFront para distribuição global:

```hcl
# cloudfront.tf
# S3 bucket para assets
resource "aws_s3_bucket" "assets" {
  bucket = "${var.project}-assets-${var.environment}"
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id
  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "assets" {
  bucket = aws_s3_bucket.assets.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "PublicReadGetObject"
      Effect    = "Allow"
      Principal = "*"
      Action    = "s3:GetObject"
      Resource  = "${aws_s3_bucket.assets.arn}/*"
    }]
  })
}

# CloudFront distribution
resource "aws_cloudfront_distribution" "cdn" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "${var.project} CDN"
  default_root_object = "index.html"
  price_class         = "PriceClass_100"  # NA/Europa

  # Origin: S3
  origin {
    domain_name = aws_s3_bucket.assets.bucket_regional_domain_name
    origin_id   = "S3-${aws_s3_bucket.assets.id}"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.oai.cloudfront_access_identity_path
    }
  }

  # Origin: ALB (API)
  origin {
    domain_name = aws_lb.app.dns_name
    origin_id   = "ALB-${aws_lb.app.name}"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
      origin_ssl_protocols   = ["TLSv1.2"]
    }
  }

  # Default cache behavior (S3)
  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3-${aws_s3_bucket.assets.id}"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 86400
    max_ttl                = 31536000
    compress               = true
  }

  # Cache behavior for API
  ordered_cache_behavior {
    path_pattern     = "/api/*"
    allowed_methods  = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "ALB-${aws_lb.app.name}"

    forwarded_values {
      query_string = true
      headers      = ["Origin", "Access-Control-Request-Headers", "Access-Control-Request-Method"]
      cookies {
        forward = "all"
      }
    }

    viewer_protocol_policy = "https-only"
    min_ttl                = 0
    default_ttl            = 0
    max_ttl                = 0
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}
```

